module freq_divbyodd #(
    parameter NUM_DIV = 5
) (
    input clk,
    input rst_n,
    output reg clk_div
);

reg [7:0] cnt1;
reg [7:0] cnt2;
reg clk_div1;
reg clk_div2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt1 <= 8'b0;
        cnt2 <= 8'b0;
        clk_div1 <= 1'b0;
        clk_div2 <= 1'b0;
        clk_div <= 1'b0;
    end else begin
        if (cnt1 == (NUM_DIV / 2) - 1)
            clk_div1 <= ~clk_div1;
        cnt1 <= cnt1 + 1;

        if (cnt2 == (NUM_DIV / 2) - 1)
            clk_div2 <= ~clk_div2;
        cnt2 <= cnt2 + 1;

        clk_div <= clk_div1 | clk_div2;
    end
end

endmodule
